draw:
var pad = 30;
var Lx = W - 2 * pad;
var k = p.n * Math.PI / Lx;
var w = 1.8;
var A = H * 0.085;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

var topY = H * 0.28;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(pad, topY); ctx.lineTo(W - pad, topY); ctx.stroke();

ctx.lineWidth = 1.6;
ctx.strokeStyle = C.faint;
ctx.beginPath();
for (var i = 0; i <= 240; i++) {
  var x1 = pad + Lx * i / 240;
  var y1 = topY - A * Math.sin(k * (x1 - pad) - w * t);
  if (i === 0) { ctx.moveTo(x1, y1); } else { ctx.lineTo(x1, y1); }
}
ctx.stroke();

ctx.strokeStyle = C.figure;
ctx.beginPath();
for (var j = 0; j <= 240; j++) {
  var x2 = pad + Lx * j / 240;
  var y2 = topY - A * Math.sin(k * (x2 - pad) + w * t);
  if (j === 0) { ctx.moveTo(x2, y2); } else { ctx.lineTo(x2, y2); }
}
ctx.stroke();

ctx.fillStyle = C.ink;
ctx.fillText("two travelling waves, opposite directions", pad, H * 0.09);

var by = H * 0.74;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(pad, by); ctx.lineTo(W - pad, by); ctx.stroke();

ctx.strokeStyle = C.faint;
ctx.setLineDash([4, 4]);
for (var s = -1; s <= 1; s += 2) {
  ctx.beginPath();
  for (var m = 0; m <= 240; m++) {
    var x3 = pad + Lx * m / 240;
    var y3 = by - s * 2 * A * Math.sin(k * (x3 - pad));
    if (m === 0) { ctx.moveTo(x3, y3); } else { ctx.lineTo(x3, y3); }
  }
  ctx.stroke();
}
ctx.setLineDash([]);

ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (var q = 0; q <= 240; q++) {
  var x4 = pad + Lx * q / 240;
  var y4 = by - 2 * A * Math.sin(k * (x4 - pad)) * Math.cos(w * t);
  if (q === 0) { ctx.moveTo(x4, y4); } else { ctx.lineTo(x4, y4); }
}
ctx.stroke();

ctx.fillStyle = C.ink;
for (var nd = 0; nd <= p.n; nd++) {
  var xn = pad + Lx * nd / p.n;
  ctx.beginPath(); ctx.arc(xn, by, 3.5, 0, 6.2832); ctx.fill();
}
ctx.fillText("their sum: nothing travels", pad, H * 0.56);
ctx.fillText("node", pad + Lx / p.n - 14, by + 16);
ctx.fillText("antinode", pad + Lx / (2 * p.n) - 22, by - 2 * A - 8);

var lam = 2 * p.L / p.n;
out.note = "n = " + p.n + " loops on L = " + p.L.toFixed(2) + " m: wavelength = " + lam.toFixed(3) + " m, nodes every " + (lam / 2).toFixed(3) + " m";

var pad = 34;
var Lx = W - 2 * pad;
var midY = H * 0.45;
var mu = p.mu / 1000;
var v = Math.sqrt(p.tension / mu);
var f = p.n * v / (2 * p.L);
var A = H * 0.2;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

ctx.fillStyle = C.faint;
ctx.fillRect(pad - 8, midY - 34, 8, 68);
ctx.fillRect(W - pad, midY - 34, 8, 68);

ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.setLineDash([3, 5]);
ctx.beginPath(); ctx.moveTo(pad, midY); ctx.lineTo(W - pad, midY); ctx.stroke();
ctx.setLineDash([]);

ctx.strokeStyle = C.faint;
for (var s = -1; s <= 1; s += 2) {
  ctx.beginPath();
  for (var m = 0; m <= 240; m++) {
    var xe = pad + Lx * m / 240;
    var ye = midY - s * A * Math.sin(p.n * Math.PI * (xe - pad) / Lx);
    if (m === 0) { ctx.moveTo(xe, ye); } else { ctx.lineTo(xe, ye); }
  }
  ctx.stroke();
}

ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 240; i++) {
  var x = pad + Lx * i / 240;
  var y = midY - A * Math.sin(p.n * Math.PI * (x - pad) / Lx) * Math.cos(2 * Math.PI * 1.2 * t);
  if (i === 0) { ctx.moveTo(x, y); } else { ctx.lineTo(x, y); }
}
ctx.stroke();

ctx.fillStyle = C.ink;
for (var nd = 0; nd <= p.n; nd++) {
  var xn = pad + Lx * nd / p.n;
  ctx.beginPath(); ctx.arc(xn, midY, 3.5, 0, 6.2832); ctx.fill();
}

ctx.strokeStyle = C.figure;
ctx.lineWidth = 1;
var yArrow = midY + A + 26;
ctx.beginPath();
ctx.moveTo(pad, yArrow); ctx.lineTo(pad + Lx / p.n, yArrow);
ctx.moveTo(pad, yArrow - 4); ctx.lineTo(pad, yArrow + 4);
ctx.moveTo(pad + Lx / p.n, yArrow - 4); ctx.lineTo(pad + Lx / p.n, yArrow + 4);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("half a wavelength", pad + 6, yArrow + 16);
ctx.fillText("fixed end", pad - 8, midY - 42);
ctx.fillText("fixed end", W - pad - 48, midY - 42);

out.note = "v = " + v.toFixed(1) + " m/s, wavelength = " + (2 * p.L / p.n).toFixed(3) + " m, f" + p.n + " = " + f.toFixed(1) + " Hz (fundamental " + (v / (2 * p.L)).toFixed(1) + " Hz)";

var pad = 26;
var pipeW = (W - 3 * pad) / 2;
var v = 343;
var L = p.L;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 2;

function envelope(x0, yMid, width, amp, harmonic, closedRight) {
  ctx.strokeStyle = C.accent;
  for (var s = -1; s <= 1; s += 2) {
    ctx.beginPath();
    for (var i = 0; i <= 200; i++) {
      var u = i / 200;
      var shape = closedRight
        ? Math.cos(harmonic * Math.PI * u / 2)
        : Math.cos(harmonic * Math.PI * u);
      var x = x0 + width * u;
      var y = yMid - s * amp * shape;
      if (i === 0) { ctx.moveTo(x, y); } else { ctx.lineTo(x, y); }
    }
    ctx.stroke();
  }
}

var amp = H * 0.14;
var yA = H * 0.3;
var yB = H * 0.75;

// open-open pipe
ctx.strokeStyle = C.rule;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(pad, yA - amp - 10); ctx.lineTo(pad + pipeW, yA - amp - 10);
ctx.moveTo(pad, yA + amp + 10); ctx.lineTo(pad + pipeW, yA + amp + 10);
ctx.stroke();
envelope(pad, yA, pipeW, amp, p.n, false);

// closed-open pipe: closed at the right
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(pad * 2 + pipeW, yB - amp - 10); ctx.lineTo(pad * 2 + 2 * pipeW, yB - amp - 10);
ctx.lineTo(pad * 2 + 2 * pipeW, yB + amp + 10);
ctx.lineTo(pad * 2 + pipeW, yB + amp + 10);
ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillRect(pad * 2 + 2 * pipeW - 6, yB - amp - 10, 6, 2 * amp + 20);
var odd = 2 * p.n - 1;
envelope(pad * 2 + pipeW, yB, pipeW, amp, odd, true);

ctx.fillStyle = C.ink;
var fOpen = p.n * v / (2 * L);
var fClosed = odd * v / (4 * L);
ctx.fillText("open at both ends, harmonic " + p.n, pad, yA - amp - 20);
ctx.fillText("antinode", pad - 4, yA + amp + 26);
ctx.fillText("antinode", pad + pipeW - 52, yA + amp + 26);
ctx.fillText("closed at one end, harmonic " + odd, pad * 2 + pipeW, yB - amp - 20);
ctx.fillText("antinode", pad * 2 + pipeW - 4, yB + amp + 26);
ctx.fillText("node", pad * 2 + 2 * pipeW - 34, yB + amp + 26);

out.note = "L = " + L.toFixed(2) + " m: open pipe " + fOpen.toFixed(0) + " Hz, stopped pipe " + fClosed.toFixed(0) + " Hz (odd harmonics only)";
